const e = $json.entry || {};
const clean = {
  customer_id: e.customer_id ?? null,
  interaction_id: e.interaction_id ?? null,
  event: String(e.event ?? 'unknown').slice(0, 100),
  classification: e.classification ?? null,
  retrieved_doc_ids: Array.isArray(e.retrieved_doc_ids) ? e.retrieved_doc_ids : [],
  decision: e.decision ?? null,
  rule_triggered: e.rule_triggered ?? null,
  ai_confidence: e.ai_confidence ?? null,
  human_involved: e.human_involved === true,
  action_taken: e.action_taken ?? null,
  success: e.success !== false,
  error_message: e.error_message ? String(e.error_message).slice(0, 1000) : null
};
return { json: { entry_b64: Buffer.from(JSON.stringify(clean)).toString('base64') } };
